class ExactStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        current_time = self.Time

        if self.spy in data.Bars:
            spy_close = data[self.spy].Close
            self.spy_sma.Update(current_time, spy_close)

        if self.aapl in data.Bars:
            aapl_close = data[self.aapl].Close
            self.aapl_rsi.Update(current_time, aapl_close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if self.spy in data.Bars and self.spy_sma.IsReady:
            self.previous_spy_close = data[self.spy].Close
            self.previous_spy_sma = self.spy_sma.Current.Value

        if self.aapl in data.Bars:
            self.previous_aapl_close = data[self.aapl].Close

        required_symbols = [self.symbols[ticker] for ticker in
                            ["SPY", "AAPL", "IBM", "BAC", "AIG"]]

        if any(symbol not in data.Bars for symbol in required_symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data[self.spy].Close
        spy_sma = self.spy_sma.Current.Value
        aapl_rsi = self.aapl_rsi.Current.Value

        spy_crossed_below = (
            previous_spy_close is not None and
            previous_spy_sma is not None and
            previous_spy_close >= previous_spy_sma and
            spy_close < spy_sma
        )

        spy_crossed_above = (
            previous_spy_close is not None and
            previous_spy_sma is not None and
            previous_spy_close <= previous_spy_sma and
            spy_close > spy_sma
        )

        if self.strategy_a_shares > 0 and spy_crossed_below:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and aapl_rsi > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crossed_above:
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / data[self.aapl].Close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_shares = quantity
