        if self.strategy_a_shares > 0 and spy_down_cross:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and rsi_ready and self.rsi.Current.Value > 60:
